using System.Reflection;

var asm = Assembly.LoadFrom(
    System.IO.Path.Combine(
        Environment.GetFolderPath(Environment.SpecialFolder.UserProfile),
        ".nuget/packages/xunit.v3.core/1.1.0/lib/net8.0/xunit.v3.core.dll"));

var cba = asm.GetType("Xunit.CollectionBehaviorAttribute");
if (cba != null) {
    Console.WriteLine("=== CollectionBehaviorAttribute ===");
    foreach (var c in cba.GetConstructors())
        Console.WriteLine("  ctor: " + string.Join(", ", c.GetParameters().Select(p => p.ParameterType.Name + " " + p.Name)));
    foreach (var p in cba.GetProperties(BindingFlags.Public | BindingFlags.Instance))
        Console.WriteLine("  prop: " + p.PropertyType.Name + " " + p.Name + (p.CanWrite ? " {get;set;}" : " {get;}"));
}

var tco = asm.GetType("Xunit.TestCaseOrdererAttribute");
